import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import { addCall, addError, emptyTally, formatTable, spinnerSuffix, statusText } from './tally'

const turn = atom({ plugin: 'cm-tool-call-counter', key: 'turn' } as const, emptyTally())
const session = atom({ plugin: 'cm-tool-call-counter', key: 'session' } as const, emptyTally())

export const register: Register = (on, options) => {
  const showInSpinner = options.showInSpinner !== false
  const showInStatus = options.showInStatus === true

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'tally',
      description: 'Show how many tool calls Claude made this turn and this session, by tool',
    })
    return next(e)
  })

  on('turn.start', async ($, e, next) => {
    await update($, turn, () => emptyTally())
    return next(e)
  })

  // Observes only: counts the call, lets it run unchanged, then counts a
  // failure. Never gates: should counting throw, the catch runs the call.
  on('tool.call', async ($, e, next) => {
    const tool = String(e.tool)
    await update($, turn, t => addCall(t, tool))
    const now = await update($, session, t => addCall(t, tool))
    if (showInStatus) $.ui.status(statusText(now))

    const ran = await next(e)

    if (ran.deny !== undefined || ran.isError === true) {
      await update($, turn, t => addError(t, tool))
      const failed = await update($, session, t => addError(t, tool))
      if (showInStatus) $.ui.status(statusText(failed))
    }
    return ran
  }).catch(($, e, next) => next(e))

  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    if (!showInSpinner) return next(e)
    const { count } = await read($, turn)
    if (count === 0) return next(e)
    return next({ ...e, props: { ...e.props, suffix: spinnerSuffix(e.props.suffix, count) } })
  })

  on('command.run', { command: 'tally' }, async $ => {
    const [now, last] = await Promise.all([read($, session), read($, turn)])
    return { text: formatTable(now, last) }
  })
}

