/**
 * Pure helpers for cm-tool-call-counter: no `$`, so they are unit-tested directly.
 */
import type { Tally } from '../types'

export function emptyTally(): Tally {
  return { count: 0, errors: 0, byTool: {} }
}

/** A new tally with one more call of `tool` (counted when the call starts). */
export function addCall(tally: Tally, tool: string): Tally {
  const prev = tally.byTool[tool] ?? { calls: 0, errors: 0 }
  return {
    count: tally.count + 1,
    errors: tally.errors,
    byTool: { ...tally.byTool, [tool]: { calls: prev.calls + 1, errors: prev.errors } },
  }
}

/** A new tally with one failed call of `tool` (counted when the call settles). */
export function addError(tally: Tally, tool: string): Tally {
  const prev = tally.byTool[tool] ?? { calls: 0, errors: 0 }
  return {
    count: tally.count,
    errors: tally.errors + 1,
    byTool: { ...tally.byTool, [tool]: { calls: prev.calls, errors: prev.errors + 1 } },
  }
}

export function plural(n: number, word: string): string {
  return `${n} ${word}${n === 1 ? '' : 's'}`
}

/** What the spinner's suffix becomes: `… · 7 tools`. */
export function spinnerSuffix(suffix: string, count: number): string {
  return `${suffix} · ${plural(count, 'tool')}`
}

/** The status line text: `🔧 12 tool calls (1 error)`. */
export function statusText(session: Tally): string {
  const errors = session.errors > 0 ? ` (${plural(session.errors, 'error')})` : ''
  return `🔧 ${plural(session.count, 'tool call')}${errors}`
}

/** Escapes a tool name for a Markdown table cell. */
function cell(text: string): string {
  return text.replace(/\|/g, '\\|')
}

/** The /tally answer: totals, then a Markdown table of the session by tool. */
export function formatTable(session: Tally, turn: Tally): string {
  const head =
    `**Tool calls** · this turn: ${turn.count} · this session: ${session.count}` +
    (session.errors > 0 ? ` (${plural(session.errors, 'error')})` : '')
  const rows = Object.entries(session.byTool).sort(([a, x], [b, y]) => y.calls - x.calls || a.localeCompare(b))
  if (rows.length === 0) return `${head}\n\nNo tool calls yet in this session.`
  const table = [
    '| Tool | Calls | Errors |',
    '| --- | ---: | ---: |',
    ...rows.map(([tool, t]) => `| ${cell(tool)} | ${t.calls} | ${t.errors} |`),
  ]
  return `${head}\n\n${table.join('\n')}`
}

