/** Calls and failed calls of one tool. */
export type ToolTally = { calls: number; errors: number }

/** Tool calls counted over a span (one turn, or the session so far). */
export type Tally = {
  count: number
  errors: number
  byTool: Record<string, ToolTally>
}

declare module 'claude-code' {
  interface PluginState {
    'cm-tool-call-counter': {
      /** Calls since the current (or last) turn started. */
      turn: Tally
      /** Calls since the mod loaded in this session. */
      session: Tally
    }
  }
}
